pub enum TomlValue {
  TomlString(String)
  TomlInt(Int64)
  TomlBool(Bool)
  TomlArray(Array[TomlValue])
  TomlTable(Map[String, TomlValue])
}

/// Convert TomlValue to Json.
pub fn TomlValue::to_json(self) -> Json {
  match self {
    TomlString(s) => Json::string(s)
    TomlInt(n) => {
      let text = n.to_string()
      Json::number(n.to_double(), repr=text)
    }
    TomlBool(b) => Json::boolean(b)
    TomlArray(arr) => {
      Json::Array(arr.map(fn(v) { v.to_json() }))
    }
    TomlTable(m) => {
      let entries: Array[(String, Json)] = []
      for (k, v) in m {
        entries.push((k, v.to_json()))
      }
      Json::object(Map::from_array(entries))
    }
  }
}
"}

{"path": "/private/tmp/prompt_demos/runs_flash-guidelines/workspaces/02/lib/parser.mbt", "content": "/// Error type for TOML parsing.
suberror TomlError {
  ParseError(String, line~ : Int, col~ : Int)
} derive(Debug)

fn TomlError::message(self) -> String {
  match self {
    ParseError(msg, line~, col~) => "TOML parse error at \{line}:\{col}: \{msg}"
  }
}

/// Parse TOML text into a Json value.
/// The top-level is always a JSON object.
pub fn parse(toml_text : String) -> Json raise TomlError {
  let root: Map[String, TomlValue] = Map([])
  let seen: Map[String, Map[String, Bool]] = Map([])
  let current_path: Array[String] = []

  let lines = toml_text.split("\n").to_array()
  for line_no = 0; line_no < lines.length(); line_no = line_no + 1 {
    let line = lines[line_no]
    let trimmed = line.trim()

    // Skip blank lines and comments
    if trimmed.is_empty() || trimmed[0] == '#' as UInt16 {
      continue
    }

    if trimmed[0] == '[' as UInt16 {
      // Table header: [key] or [key.subkey]
      let end_bracket = pos_of_char(trimmed, ']', 1)
      if end_bracket == -1 {
        raise ParseError("unclosed table header", line=line_no + 1, col=1)
      }
      let table_key_str = trimmed.sub(start=1, end=end_bracket).trim().to_owned()
      if table_key_str.is_empty() {
        raise ParseError("empty table key", line=line_no + 1, col=2)
      }
      let parts = table_key_str.split(".").to_array()
      // Ensure each part is a valid bare key
      for i = 0; i < parts.length(); i = i + 1 {
        let part = parts[i].trim()
        if !is_valid_bare_key(part) {
          raise ParseError("invalid table key: \"\{part}\"", line=line_no + 1, col=1)
        }
        parts[i] = part
      }

      // Navigate/create table structure
      let mut table = root
      let mut table_seen = seen
      for i = 0; i < parts.length(); i = i + 1 {
        let part = parts[i]
        ensure_table_exists(table, table_seen, part, line_no + 1) raise
        let next_val = table[part]
        match next_val {
          TomlTable(inner) => {
            table = inner
            if !table_seen.contains(part) {
              table_seen[part] = Map([])
            }
            table_seen = table_seen[part]
          }
          _ => {
            raise ParseError("key \"\{part}\" is not a table", line=line_no + 1, col=1)
          }
        }
      }
      // Set the last part as the current table marker
      // We already navigated to it; we just need to mark the path
      current_path = parts
    } else {
      // Key-value pair
      let eq_pos = find_unquoted_eq(trimmed)
      if eq_pos == -1 {
        raise ParseError("invalid key-value pair (no '=' found)", line=line_no + 1, col=1)
      }
      let key_part = trimmed.sub(start=0, end=eq_pos).trim().to_owned()
      let val_part = trimmed.sub(start=eq_pos + 1).trim().to_owned()

      let key_parts = key_part.split(".").to_array()
      for i = 0; i < key_parts.length(); i = i + 1 {
        let kp = key_parts[i].trim()
        if !is_valid_bare_key(kp) {
          raise ParseError("invalid key: \"\{kp}\"", line=line_no + 1, col=1)
        }
        key_parts[i] = kp
      }

      let value = parse_value(val_part, line_no + 1) raise

      // Insert into the appropriate table
      // Navigate to the parent table based on current_path and key_parts
      let mut table = root
      let mut table_seen = seen

      // Navigate through current_path
      for i = 0; i < current_path.length(); i = i + 1 {
        let part = current_path[i]
        match table[part] {
          TomlTable(inner) => {
            table = inner
            if table_seen.contains(part) {
              table_seen = table_seen[part]
            } else {
              table_seen = Map([])
            }
          }
          _ => {
            raise ParseError("internal error: path component \"\{part}\" not a table",
              line=line_no + 1, col=1)
          }
        }
      }

      // Navigate through key_parts except the last
      for i = 0; i < key_parts.length() - 1; i = i + 1 {
        let part = key_parts[i]
        ensure_table_exists(table, table_seen, part, line_no + 1) raise
        let next_val = table[part]
        match next_val {
          TomlTable(inner) => {
            table = inner
            if !table_seen.contains(part) {
              table_seen[part] = Map([])
            }
            table_seen = table_seen[part]
          }
          _ => {
            raise ParseError("key \"\{part}\" is not a table", line=line_no + 1, col=1)
          }
        }
      }

      // Set the final key
      let final_key = key_parts[key_parts.length() - 1]
      // Check for duplicate
      if table_seen.contains(final_key) {
        raise ParseError("duplicate key: \"\{final_key}\"", line=line_no + 1, col=1)
      }
      table_seen[final_key] = true
      table[final_key] = value
    }
  }

  // Convert root to JSON
  toml_table_to_json(root)
}

fn toml_table_to_json(m : Map[String, TomlValue]) -> Json {
  let entries: Array[(String, Json)] = []
  for (k, v) in m {
    entries.push((k, v.to_json()))
  }
  // Sort keys for deterministic output
  entries.sort(fn(a, b) { a.0.compare(b.0) })
  let om: Map[String, Json] = Map([])
  for (k, v) in entries {
    om[k] = v
  }
  Json::object(om)
}

fn ensure_table_exists(table : Map[String, TomlValue], seen : Map[String, Map[String, Bool]],
    key : String, line : Int) -> Unit raise TomlError {
  if table.contains(key) {
    match table[key] {
      TomlTable(_) => () // already exists
      _ => raise ParseError("key \"\{key}\" already exists and is not a table", line=line, col=1)
    }
  } else {
    table[key] = TomlTable(Map([]))
    if !seen.contains(key) {
      seen[key] = Map([])
    }
  }
}

fn is_valid_bare_key(s : String) -> Bool {
  if s.is_empty() { return false }
  for c in s {
    if !is_bare_key_char(c) { return false }
  }
  true
}

fn is_bare_key_char(c : Char) -> Bool {
  (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
    c == '_' || c == '-'
}

fn pos_of_char(s : StringView, target : Char, start : Int) -> Int {
  let mut i = start
  while i < s.char_length() {
    match s.get_char(i) {
      Some(c) if c == target => return i
      _ => i = i + 1
    }
  }
  -1
}

fn find_unquoted_eq(s : StringView) -> Int {
  let mut depth = 0
  let mut in_string = false
  let mut i = 0
  while i < s.char_length() {
    match s.get_char(i) {
      Some(c) => {
        if in_string {
          if c == '\\' {
            i = i + 2
            continue
          }
          if c == '"' {
            in_string = false
          }
        } else {
          if c == '"' {
            in_string = true
          } else if c == '[' {
            depth = depth + 1
          } else if c == ']' {
            depth = depth - 1
          } else if c == '=' && depth == 0 {
            return i
          }
        }
      }
      None => ()
    }
    i = i + 1
  }
  -1
}

fn parse_value(text : StringView, line : Int) -> TomlValue raise TomlError {
  let trimmed = text.trim()
  if trimmed.is_empty() {
    raise ParseError("empty value", line=line, col=1)
  }
  let first = trimmed.get_char(0)
  match first {
    Some('"') => parse_string(trimmed, line)
    Some('t') | Some('f') => parse_boolean(trimmed, line)
    Some('[') => parse_array(trimmed, line)
    Some(c) if is_digit(c) || c == '-' || c == '+' => parse_integer(trimmed, line)
    _ => raise ParseError("unexpected value: \"\{trimmed}\"", line=line, col=1)
  }
}

fn parse_string(text : StringView, line : Int) -> TomlValue raise TomlError {
  if text.get_char(0) != Some('"') {
    raise ParseError("expected opening quote", line=line, col=1)
  }
  let mut result = StringBuilder::new()
  let mut i = 1
  while i < text.char_length() {
    match text.get_char(i) {
      Some('"') => {
        // End of string
        // Check for trailing content after closing quote
        let rest = text.sub(start=i + 1).to_owned()
        if rest.trim().is_empty() {
          return TomlString(result.to_string())
        } else {
          raise ParseError("unexpected content after string: \"\{rest.trim()}\"", line=line, col=i + 1)
        }
      }
      Some('\\') => {
        i = i + 1
        match text.get_char(i) {
          Some('"') => { result.write_char('"'); i = i + 1 }
          Some('\\') => { result.write_char('\\'); i = i + 1 }
          Some('n') => { result.write_char('\n'); i = i + 1 }
          Some('t') => { result.write_char('\t'); i = i + 1 }
          Some(c) => raise ParseError("invalid escape: \\\{c}", line=line, col=i)
          None => raise ParseError("unterminated escape", line=line, col=i)
        }
      }
      Some(c) => {
        result.write_char(c)
        i = i + 1
      }
      None => raise ParseError("unterminated string", line=line, col=i)
    }
  }
  raise ParseError("unterminated string", line=line, col=i)
}

fn parse_boolean(text : StringView, line : Int) -> TomlValue raise TomlError {
  if text.starts_with("true") {
    let rest = text.sub(start=4).to_owned()
    if rest.trim().is_empty() {
      TomlBool(true)
    } else {
      raise ParseError("unexpected content after \"true\"", line=line, col=5)
    }
  } else if text.starts_with("false") {
    let rest = text.sub(start=5).to_owned()
    if rest.trim().is_empty() {
      TomlBool(false)
    } else {
      raise ParseError("unexpected content after \"false\"", line=line, col=6)
    }
  } else {
    raise ParseError("invalid boolean", line=line, col=1)
  }
}

fn parse_integer(text : StringView, line : Int) -> TomlValue raise TomlError {
  let trimmed = text.trim()
  let mut end = 0
  let chars = trimmed.to_array()
  if chars.length() > 0 && (chars[0] == '-' || chars[0] == '+') {
    end = 1
  }
  while end < chars.length() && is_digit(chars[end]) {
    end = end + 1
  }
  if end == 0 || (end == 1 && (trimmed.get_char(0) == Some('-') || trimmed.get_char(0) == Some('+'))) {
    raise ParseError("invalid integer: \"\{trimmed}\"", line=line, col=1)
  }
  let num_str = trimmed.sub(start=0, end=end).to_owned()
  let n: Int64 = @string.from_str(num_str)
  let rest = trimmed.sub(start=end).trim().to_owned()
  if rest.is_empty() {
    TomlInt(n)
  } else {
    raise ParseError("unexpected content after integer: \"\{rest}\"", line=line, col=end + 1)
  }
}

fn parse_array(text : StringView, line : Int) -> TomlValue raise TomlError {
  if text.get_char(0) != Some('[') {
    raise ParseError("expected '['", line=line, col=1)
  }
  let mut items: Array[TomlValue] = []
  let mut i = 1
  // Skip whitespace
  while i < text.char_length() {
    match text.get_char(i) {
      Some(']') => {
        return TomlArray(items)
      }
      Some(c) if is_whitespace(c) || c == '\n' || c == ',' => {
        i = i + 1
      }
      _ => {
        // Find the end of this value
        let val_start = i
        // Parse the value
        let val_end = find_value_end(text, i, line) raise
        let val_text = text.sub(start=val_start, end=val_end).to_owned()
        let val = parse_value(val_text, line) raise
        items.push(val)
        i = val_end
        // Skip whitespace and optional comma
        while i < text.char_length() {
          match text.get_char(i) {
            Some(c) if is_whitespace(c) || c == '\n' => { i = i + 1 }
            Some(',') => { i = i + 1 }
            _ => break
          }
        }
      }
    }
  }
  raise ParseError("unterminated array", line=line, col=i)
}

fn find_value_end(text : StringView, start : Int, line : Int) -> Int raise TomlError {
  let mut depth = 0
  let mut in_string = false
  let mut i = start
  while i < text.char_length() {
    match text.get_char(i) {
      Some(c) => {
        if in_string {
          if c == '\\' { i = i + 2; continue }
          if c == '"' { in_string = false }
        } else {
          if c == '"' { in_string = true }
          else if c == '[' { depth = depth + 1 }
          else if c == ']' {
            if depth == 0 {
              return i + 1 // include the closing bracket
            }
            depth = depth - 1
            if depth == 0 {
              return i + 1
            }
          }
          else if c == ',' && depth == 0 && !in_string {
            return i
          }
          else if depth == 0 && (c == '\n' || c == '#') {
            return i
          }
        }
      }
      None => ()
    }
    i = i + 1
  }
  i
}

fn is_digit(c : Char) -> Bool {
  c >= '0' && c <= '9'
}

fn is_whitespace(c : Char) -> Bool {
  c == ' ' || c == '\t' || c == '\r'
}
"}

{"path": "/private/tmp/prompt_demos/runs_flash-guidelines/workspaces/02/lib/parser.mbt", "content": "/// Error type for TOML parsing.
suberror TomlError {
  ParseError(String, line~ : Int, col~ : Int)
} derive(Debug)

/// Parsed TOML value types.
pub enum TomlValue {
  TomlString(String)
  TomlInt(Int64)
  TomlBool(Bool)
  TomlArray(Array[TomlValue])
  TomlTable(Map[String, TomlValue])
}

/// Convert a TomlValue to a Json value.
pub fn TomlValue::to_json(self) -> Json {
  match self {
    TomlString(s) => Json::string(s)
    TomlInt(n) => {
      let text = n.to_string()
      Json::number(n.to_double(), repr=text)
    }
    TomlBool(b) => Json::boolean(b)
    TomlArray(arr) => {
      let ja: Array[Json] = arr.map(fn(v) { v.to_json() })
      Json::array(ja)
    }
    TomlTable(m) => {
      let entries: Array[(String, Json)] = []
      for (k, v) in m {
        entries.push((k, v.to_json()))
      }
      entries.sort(fn(a, b) { a.0.compare(b.0) })
      let om: Map[String, Json] = Map([])
      for (k, v) in entries {
        om[k] = v
      }
      Json::object(om)
    }
  }
}

/// Parse TOML text into a Json value.
pub fn parse(toml_text : String) -> Json raise TomlError {
  let root: Map[String, TomlValue] = Map([])
  // Track seen keys per table path to detect duplicates.
  // We store a map of key -> true for each table level.
  // Instead of nested Maps, we use a stack of seen maps.
  let root_seen: Map[String, Bool] = Map([])
  let mut seen_stack: Array[Map[String, Bool]] = [root_seen]
  let mut table_path: Array[String] = []

  let lines = toml_text.split("\n")
  let line_arr: Array[String] = lines.to_array()
  for line_no = 0; line_no < line_arr.length(); line_no = line_no + 1 {
    let line = line_arr[line_no]
    let trimmed = line.trim()

    // Skip blank lines and comments
    if trimmed.is_empty() {
      continue
    }
    if starts_with_hash(trimmed) {
      continue
    }

    if starts_with_bracket(trimmed) {
      // Table header: [key] or [key.subkey]
      let end_bracket = pos_of_char(trimmed, ']', 1)
      if end_bracket == -1 {
        raise ParseError("unclosed table header", line=line_no + 1, col=1)
      }
      let raw_key = trimmed.sub(start=1, end=end_bracket).to_owned()
      let table_key_str = raw_key.trim()
      if table_key_str.is_empty() {
        raise ParseError("empty table key", line=line_no + 1, col=2)
      }
      let parts: Array[String] = table_key_str.split(".").map(fn(s) { s.trim() })
      for p in parts {
        if !is_valid_bare_key(p) {
          raise ParseError("invalid table key: \"\{p}\"", line=line_no + 1, col=1)
        }
      }

      // Navigate/create tables
      ensure_table_path(root, parts, line_no + 1) raise
      table_path = parts

      // Build new seen stack for the final table
      seen_stack = [root_seen]
      for i = 0; i < parts.length(); i = i + 1 {
        let part = parts[i]
        let current_seen = seen_stack[seen_stack.length() - 1]
        if !current_seen.contains(part) {
          current_seen[part] = true
        }
        let child_seen: Map[String, Bool] = Map([])
        seen_stack.push(child_seen)
      }
    } else {
      // Key-value pair
      let eq_pos = find_unquoted_eq(trimmed)
      if eq_pos == -1 {
        raise ParseError("invalid key-value pair (no '=' found)", line=line_no + 1, col=1)
      }
      let key_part = trimmed.sub(start=0, end=eq_pos).to_owned().trim()
      let val_part = trimmed.sub(start=eq_pos + 1).to_owned().trim()

      let key_parts: Array[String] = key_part.split(".").map(fn(s) { s.trim() })
      for kp in key_parts {
        if !is_valid_bare_key(kp) {
          raise ParseError("invalid key: \"\{kp}\"", line=line_no + 1, col=1)
        }
      }

      let value = parse_toml_value(val_part, line_no + 1) raise

      // Navigate to the right table
      let mut table = root
      for i = 0; i < table_path.length(); i = i + 1 {
        let part = table_path[i]
        match table[part] {
          TomlTable(inner) => table = inner
          _ => raise ParseError("internal: path not a table", line=line_no + 1, col=1)
        }
      }

      // Navigate through key_parts except last
      for i = 0; i < key_parts.length() - 1; i = i + 1 {
        let part = key_parts[i]
        ensure_table_exists(table, part, line_no + 1) raise
        match table[part] {
          TomlTable(inner) => table = inner
          _ => raise ParseError("key is not a table", line=line_no + 1, col=1)
        }
      }

      // Set final key with duplicate check
      let final_key = key_parts[key_parts.length() - 1]
      if table.contains(final_key) {
        raise ParseError("duplicate key: \"\{final_key}\"", line=line_no + 1, col=1)
      }
      table[final_key] = value
    }
  }

  // Convert root to JSON
  root_to_json(root)
}

fn root_to_json(m : Map[String, TomlValue]) -> Json {
  let entries: Array[(String, Json)] = []
  for (k, v) in m {
    entries.push((k, v.to_json()))
  }
  entries.sort(fn(a, b) { a.0.compare(b.0) })
  let om: Map[String, Json] = Map([])
  for (k, v) in entries {
    om[k] = v
  }
  Json::object(om)
}

fn ensure_table_path(root : Map[String, TomlValue], parts : Array[String],
    line : Int) -> Unit raise TomlError {
  let mut table = root
  for i = 0; i < parts.length(); i = i + 1 {
    let part = parts[i]
    if table.contains(part) {
      match table[part] {
        TomlTable(inner) => table = inner
        _ => raise ParseError("key \"\{part}\" is not a table", line=line, col=1)
      }
    } else {
      let new_table: Map[String, TomlValue] = Map([])
      table[part] = TomlTable(new_table)
      table = new_table
    }
  }
}

fn ensure_table_exists(table : Map[String, TomlValue], key : String,
    line : Int) -> Unit raise TomlError {
  if table.contains(key) {
    match table[key] {
      TomlTable(_) => ()
      _ => raise ParseError("key \"\{key}\" exists and is not a table", line=line, col=1)
    }
  } else {
    table[key] = TomlTable(Map([]))
  }
}

fn starts_with_hash(s : String) -> Bool {
  s.char_length() > 0 && s.get_char(0) == Some('#')
}

fn starts_with_bracket(s : String) -> Bool {
  s.char_length() > 0 && s.get_char(0) == Some('[')
}

fn is_valid_bare_key(s : String) -> Bool {
  if s.is_empty() { return false }
  for c in s {
    if !is_bare_key_char(c) { return false }
  }
  true
}

fn is_bare_key_char(c : Char) -> Bool {
  (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') ||
    c == '_' || c == '-'
}

fn pos_of_char(s : String, target : Char, start : Int) -> Int {
  let mut i = start
  while i < s.char_length() {
    match s.get_char(i) {
      Some(c) if c == target => return i
      _ => i = i + 1
    }
  }
  -1
}

fn find_unquoted_eq(s : String) -> Int {
  let mut depth = 0
  let mut in_string = false
  let mut i = 0
  while i < s.char_length() {
    match s.get_char(i) {
      Some(c) => {
        if in_string {
          if c == '\\' {
            i = i + 2
            continue
          }
          if c == '"' {
            in_string = false
          }
        } else {
          if c == '"' {
            in_string = true
          } else if c == '[' {
            depth = depth + 1
          } else if c == ']' {
            depth = depth - 1
          } else if c == '=' && depth == 0 {
            return i
          }
        }
      }
      None => ()
    }
    i = i + 1
  }
  -1
}

fn parse_toml_value(text : String, line : Int) -> TomlValue raise TomlError {
  let trimmed = text.trim()
  if trimmed.is_empty() {
    raise ParseError("empty value", line=line, col=1)
  }
  match trimmed.get_char(0) {
    Some('"') => parse_toml_string(trimmed, line)
    Some('t') => parse_toml_bool(trimmed, line)
    Some('f') => parse_toml_bool(trimmed, line)
    Some('[') => parse_toml_array(trimmed, line)
    Some(c) if is_digit(c) || c == '-' || c == '+' => parse_toml_int(trimmed, line)
    Some(c) => raise ParseError("unexpected character: '\{c}'", line=line, col=1)
    None => raise ParseError("unexpected end of value", line=line, col=1)
