fn parse_toml_string(text : String, line : Int) -> TomlValue raise TomlError {
  let len = text.char_length()
  if len < 2 || text.get_char(0) != Some('"') {
    raise ParseError("expected opening quote", line=line, col=1)
  }
  let mut result = StringBuilder::new()
  let mut i = 1
  while i < len {
    match text.get_char(i) {
      Some('"') => {
        // Check for trailing content
        let rest = text.sub(start=i + 1).to_owned().trim()
        if rest.is_empty() {
          return TomlString(result.to_string())
        } else {
          raise ParseError("unexpected content after string: \"\{rest}\"", line=line, col=i + 1)
        }
      }
      Some('\\') => {
        i = i + 1
        if i >= len {
          raise ParseError("unterminated escape", line=line, col=i)
        }
        match text.get_char(i) {
          Some('"') => { result.write_char('"'); i = i + 1 }
          Some('\\') => { result.write_char('\\'); i = i + 1 }
          Some('n') => { result.write_char('\n'); i = i + 1 }
          Some('t') => { result.write_char('\t'); i = i + 1 }
          Some(c) => raise ParseError("invalid escape: \\\{c}", line=line, col=i)
          None => raise ParseError("unterminated escape", line=line, col=i)
        }
      }
      Some(c) => {
        result.write_char(c)
        i = i + 1
      }
      None => raise ParseError("unterminated string", line=line, col=i)
    }
  }
  raise ParseError("unterminated string", line=line, col=i)
}

fn parse_toml_bool(text : String, line : Int) -> TomlValue raise TomlError {
  if text.starts_with("true") {
    let rest = text.sub(start=4).to_owned().trim()
    if rest.is_empty() {
      TomlBool(true)
    } else {
      raise ParseError("unexpected content after \"true\"", line=line, col=5)
    }
  } else if text.starts_with("false") {
    let rest = text.sub(start=5).to_owned().trim()
    if rest.is_empty() {
      TomlBool(false)
    } else {
      raise ParseError("unexpected content after \"false\"", line=line, col=6)
    }
  } else {
    raise ParseError("invalid boolean value", line=line, col=1)
  }
}

fn parse_toml_int(text : String, line : Int) -> TomlValue raise TomlError {
  let trimmed = text.trim()
  let chars: Array[Char] = trimmed.to_array()
  let len = chars.length()
  let mut end = 0
  if end < len && (chars[end] == '-' || chars[end] == '+') {
    end = 1
  }
  while end < len && is_digit(chars[end]) {
    end = end + 1
  }
  if end == 0 || (end == 1 && (chars[0] == '-' || chars[0] == '+')) {
    raise ParseError("invalid integer: \"\{trimmed}\"", line=line, col=1)
  }
  let num_str = trimmed.sub(start=0, end=end).to_owned()
  let n: Int64 = @string.from_str(num_str)
  let rest = trimmed.sub(start=end).to_owned().trim()
  if rest.is_empty() {
    TomlInt(n)
  } else {
    raise ParseError("unexpected content after integer: \"\{rest}\"", line=line, col=end + 1)
  }
}

fn parse_toml_array(text : String, line : Int) -> TomlValue raise TomlError {
  if text.get_char(0) != Some('[') {
    raise ParseError("expected '['", line=line, col=1)
  }
  let mut items: Array[TomlValue] = []
  let len = text.char_length()
  let mut i = 1
  if i < len && text.get_char(i) == Some(']') {
    return TomlArray(items)
  }
  while i < len {
    // skip whitespace and commas
    let mut ch = text.get_char(i)
    while ch == Some(' ') || ch == Some('\t') || ch == Some('\n') || ch == Some('\r') || ch == Some(',') {
      i = i + 1
      if i >= len { break }
      ch = text.get_char(i)
    }
    if i >= len {
      raise ParseError("unterminated array", line=line, col=i)
    }
    if text.get_char(i) == Some(']') {
      return TomlArray(items)
    }
    // find end of value
    let val_start = i
    i = find_array_value_end(text, i, line) raise
    let val_text = text.sub(start=val_start, end=i).to_owned()
    let val = parse_toml_value(val_text, line) raise
    items.push(val)
  }
  raise ParseError("unterminated array", line=line, col=i)
