            depth = depth - 1
          }
          else if c == ',' && depth == 0 {
            return i
          }
        }
      }
      None => ()
    }
    i = i + 1
  }
  i
}

fn is_digit(c : Char) -> Bool {
  c >= '0' && c <= '9'
}
