/// Parse TOML text into a Json value.
pub fn parse(toml_text : String) -> Json raise TomlError {
  let root: Map[String, TomlValue] = Map([])
  // Track seen keys per table path to detect duplicates.
  let root_seen: Map[String, Bool] = Map([])
  let mut seen_stack: Array[Map[String, Bool]] = [root_seen]
  let mut table_path: Array[String] = []

  let line_arr: Array[String] = toml_text.split("\n").to_array()
  for line_no = 0; line_no < line_arr.length(); line_no = line_no + 1 {
    let line = line_arr[line_no]
    let trimmed = line.trim()

    // Skip blank lines and comments
    if trimmed.is_empty() {
      continue
    }
    if trimmed.has_prefix("#") {
      continue
    }

    if trimmed.has_prefix("[") {
      // Table header: [key] or [key.subkey]
      let end_bracket = pos_of_char(trimmed, ']', 1)
      if end_bracket == -1 {
        raise ParseError("unclosed table header", line=line_no + 1, col=1)
      }
      let raw_key = trimmed.sub(start=1, end=end_bracket).to_owned()
      let table_key_str = raw_key.trim()
      if table_key_str.is_empty() {
        raise ParseError("empty table key", line=line_no + 1, col=2)
      }
