      for p in parts {
        if !is_valid_bare_key(p) {
          raise ParseError("invalid table key: \"\{p}\"", line=line_no + 1, col=1)
        }
      }

      // Navigate/create tables
      ensure_table_path(root, parts, line_no + 1) raise
      table_path = parts

      // Build new seen stack for the final table
      seen_stack = [root_seen]
      for i = 0; i < parts.length(); i = i + 1 {
        let part = parts[i]
        let current_seen = seen_stack[seen_stack.length() - 1]
        if !current_seen.contains(part) {
          current_seen[part] = true
        }
        let child_seen: Map[String, Bool] = Map([])
        seen_stack.push(child_seen)
      }
    } else {
      // Key-value pair
      let eq_pos = find_unquoted_eq(trimmed)
      if eq_pos == -1 {
        raise ParseError("invalid key-value pair (no '=' found)", line=line_no + 1, col=1)
      }
      let key_part = trimmed.sub(start=0, end=eq_pos).to_owned().trim()
      let val_part = trimmed.sub(start=eq_pos + 1).to_owned().trim()

      let key_parts: Array[String] = key_part.split(".").map(fn(s) { s.trim() })
      for kp in key_parts {
        if !is_valid_bare_key(kp) {
          raise ParseError("invalid key: \"\{kp}\"", line=line_no + 1, col=1)
        }
      }

      let value = parse_toml_value(val_part, line_no + 1) raise

      // Navigate to the right table based on table_path
      let mut table = root
      for i = 0; i < table_path.length(); i = i + 1 {
        let part = table_path[i]
        match table[part] {
          TomlTable(inner) => table = inner
          _ => raise ParseError("internal: path not a table", line=line_no + 1, col=1)
