      }

      // Navigate through key_parts except last
      for i = 0; i < key_parts.length() - 1; i = i + 1 {
        let part = key_parts[i]
        ensure_table_exists(table, part, line_no + 1) raise
        match table[part] {
          TomlTable(inner) => table = inner
          _ => raise ParseError("key is not a table", line=line_no + 1, col=1)
