  root_to_json(root)
}

fn root_to_json(m : Map[String, TomlValue]) -> Json {
  let entries: Array[(String, Json)] = []
  for (k, v) in m {
    entries.push((k, v.to_json()))
  }
  entries.sort(fn(a, b) { a.0.compare(b.0) })
  let om: Map[String, Json] = Map([])
  for (k, v) in entries {
    om[k] = v
  }
  Json::object(om)
}

fn ensure_table_path(root : Map[String, TomlValue], parts : Array[String],
    line : Int) -> Unit raise TomlError {
  let mut table = root
  for i = 0; i < parts.length(); i = i + 1 {
    let part = parts[i]
    if table.contains(part) {
      match table[part] {
        TomlTable(inner) => table = inner
        _ => raise ParseError("key \"\{part}\" is not a table", line=line, col=1)
      }
    } else {
      let new_table: Map[String, TomlValue] = Map([])
      table[part] = TomlTable(new_table)
      table = new_table
    }
  }
}

fn ensure_table_exists(table : Map[String, TomlValue], key : String,
    line : Int) -> Unit raise TomlError {
  if table.contains(key) {
    match table[key] {
      TomlTable(_) => ()
      _ => raise ParseError("key \"\{key}\" exists and is not a table", line=line, col=1)
    }
  } else {
    table[key] = TomlTable(Map([]))
