  TomlInt(Int64)
  TomlBool(Bool)
  TomlArray(Array[TomlValue])
  TomlTable(Map[String, TomlValue])
}

/// Convert a TomlValue to a Json value.
fn to_json(self : TomlValue) -> Json {
  match self {
    TomlString(s) => Json::string(s)
    TomlInt(n) => {
      let text = n.to_string()
      Json::number(n.to_double(), repr=text)
    }
    TomlBool(b) => Json::boolean(b)
    TomlArray(arr) => {
      let ja: Array[Json] = arr.map(fn(v) { v.to_json() })
      Json::array(ja)
    }
    TomlTable(m) => {
      let entries: Array[(String, Json)] = []
      for kv in m {
        let (k, v) = kv
        entries.push((k, v.to_json()))
      }
      // Sort by keys for deterministic output
      let keys: Array[String] = entries.map(fn(t) { t.0 })
      keys.sort()
      let om: Map[String, Json] = Map([])
      for k in keys {
        for kv in entries {
          let (ek, ev) = kv
          if ek == k {
            om[k] = ev
            break
          }
        }
      }
      Json::object(om)
    }
  }
}

