        for kv in entries {
          let (ek, ev) = kv
          if ek == k {
            om[k] = ev
            break
          }
        }
      }
      Json::object(om)
    }
  }
}

/// Parse TOML text into a Json value.
pub fn parse(toml_text : String) -> Json raise TomlError {
  let root: Map[String, TomlValue] = Map([])
  let mut table_path: Array[String] = []

  let lines: Array[String] = toml_text.split("\n").map(fn(sv) { sv.to_owned() }).to_array()
  for line_no = 0; line_no < lines.length(); line_no = line_no + 1 {
    let trimmed = lines[line_no].trim().to_owned()

    // Skip blank lines and comments
    if trimmed.is_empty() {
      continue
    }
    if trimmed.has_prefix("#") {
      continue
    }

    if trimmed.has_prefix("[") {
      // Table header: [key] or [key.subkey]
      let end_bracket = pos_of_char(trimmed, ']', 1)
      if end_bracket == -1 {
        raise ParseError("unclosed table header", line=line_no + 1, col=1)
      }
      let raw_key = trimmed.sub(start=1, end=end_bracket).to_owned()
      let table_key_str = raw_key.trim().to_owned()
      if table_key_str.is_empty() {
        raise ParseError("empty table key", line=line_no + 1, col=2)
      }
      let parts: Array[String] = table_key_str.split(".").map(fn(sv) { sv.trim().to_owned() }).to_array()
      for p in parts {
        if !is_valid_bare_key(p) {
          raise ParseError("invalid table key: \"\{p}\"", line=line_no + 1, col=1)
        }
      }

      // Navigate/create tables
      ensure_table_path(root, parts, line_no + 1)
      table_path = parts
    } else {
      // Key-value pair
      let eq_pos = find_unquoted_eq(trimmed)
      if eq_pos == -1 {
        raise ParseError("invalid key-value pair (no '=' found)", line=line_no + 1, col=1)
      }
      let key_part = trimmed.sub(start=0, end=eq_pos).to_owned().trim().to_owned()
      let val_part = trimmed.sub(start=eq_pos + 1).to_owned().trim().to_owned()

      let key_parts: Array[String] = key_part.split(".").map(fn(sv) { sv.trim().to_owned() }).to_array()
      for kp in key_parts {
        if !is_valid_bare_key(kp) {
          raise ParseError("invalid key: \"\{kp}\"", line=line_no + 1, col=1)
        }
      }

      let value = parse_toml_value(val_part, line_no + 1)

      // Navigate to the right table based on table_path
      let mut table = root
      for i = 0; i < table_path.length(); i = i + 1 {
        let part = table_path[i]
        match table[part] {
          TomlTable(inner) => table = inner
          _ => raise ParseError("internal: path not a table", line=line_no + 1, col=1)
        }
      }

      // Navigate through key_parts except last
      for i = 0; i < key_parts.length() - 1; i = i + 1 {
        let part = key_parts[i]
        ensure_table_exists(table, part, line_no + 1)
        match table[part] {
          TomlTable(inner) => table = inner
          _ => raise ParseError("key is not a table", line=line_no + 1, col=1)
        }
      }

      // Set final key with duplicate check
      let final_key = key_parts[key_parts.length() - 1]
      if table.contains(final_key) {
        raise ParseError("duplicate key: \"\{final_key}\"", line=line_no + 1, col=1)
      }
      table[final_key] = value
    }
  }

  // Convert root to JSON
  root_to_json(root)
}

fn root_to_json(m : Map[String, TomlValue]) -> Json {
  let entries: Array[(String, Json)] = []
  for kv in m {
    let (k, v) = kv
    entries.push((k, v.to_json()))
  }
  let keys: Array[String] = entries.map(fn(t) { t.0 })
  keys.sort()
  let om: Map[String, Json] = Map([])
  for k in keys {
    for kv in entries {
      let (ek, ev) = kv
      if ek == k {
        om[k] = ev
        break
      }
    }
  }
  Json::object(om)
}

fn ensure_table_path(root : Map[String, TomlValue], parts : Array[String],
    line : Int) -> Unit raise TomlError {
  let mut table = root
  for i = 0; i < parts.length(); i = i + 1 {
    let part = parts[i]
    if table.contains(part) {
      match table[part] {
        TomlTable(inner) => table = inner
        _ => raise ParseError("key \"\{part}\" is not a table", line=line, col=1)
      }
    } else {
      let new_table: Map[String, TomlValue] = Map([])
      table[part] = TomlTable(new_table)
      table = new_table
    }
  }
}

fn ensure_table_exists(table : Map[String, TomlValue], key : String,
    line : Int) -> Unit raise TomlError {
  if table.contains(key) {
    match table[key] {
      TomlTable(_) => ()
      _ => raise ParseError("key \"\{key}\" exists and is not a table", line=line, col=1)
